{"kind":"tool","id":"l79jXFllErU","toolName":"write_file","input":{"path":"lib/firebase/client.ts","content":""use client";

import { getApps, initializeApp, type FirebaseApp } from "firebase/app";
import { connectAuthEmulator, getAuth, type Auth } from "firebase/auth";
import {
  connectFirestoreEmulator,
  getFirestore,
  type Firestore,
} from "firebase/firestore";

const config = {
  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY,
  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID,
  storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID,
  databaseURL: process.env.NEXT_PUBLIC_FIREBASE_DATABASE_URL,
  measurementId: process.env.NEXT_PUBLIC_FIREBASE_MEASUREMENT_ID,
};

export const FIREBASE_READY = Boolean(config.apiKey && config.projectId && config.authDomain);

let app: FirebaseApp | null = null;
let authInstance: Auth | null = null;
let dbInstance: Firestore | null = null;
let emulatorsWired = false;

export function getFirebaseApp(): FirebaseApp | null {
  if (!FIREBASE_READY) return null;
  if (!app) {
    app = getApps()[0] ?? initializeApp(config);
  }
  return app;
}

export function getFirebaseAuth(): Auth | null {
  const instance = getFirebaseApp();
  if (!instance) return null;
  if (!authInstance) {
    authInstance = getAuth(instance);
    const emulatorHost = process.env.NEXT_PUBLIC_FIREBASE_EMULATOR_HOST;
    if (process.env.NEXT_PUBLIC_USE_FIREBASE_EMULATOR === "true" && emulatorHost && !emulatorsWired) {
      try {
        connectAuthEmulator(authInstance, `http://${emulatorHost}`, { disableWarnings: true });
      } catch {
        /* already connected */
      }
    }
  }
  return authInstance;
}

export function getDb(): Firestore | null {
  const instance = getFirebaseApp();
  if (!instance) return null;
  if (!dbInstance) {
    dbInstance = getFirestore(instance);
    const emulatorHost = process.env.NEXT_PUBLIC_FIREBASE_EMULATOR_HOST;
    if (process.env.NEXT_PUBLIC_USE_FIREBASE_EMULATOR === "true" && emulatorHost && !emulatorsWired) {
      emulatorsWired = true;
      try {
        const [host, port] = emulatorHost.split(":");
        connectFirestoreEmulator(dbInstance, host ?? "127.0.0.1", Number(port ?? 8080));
      } catch {
        /* already connected */
      }
    }
  }
  return dbInstance;
}

export function assertDb(): Firestore {
  const db = getDb();
  if (!db) {
    throw new Error(
      "Firebase is not configured. Add NEXT_PUBLIC_FIREBASE_* variables to .env.local (see .env.example).",
    );
  }
  return db;
}
