interface LiveState<T> {
  data: T;
  loading: boolean;
  error: string | null;
}

function useLiveCollection<T>(
  subscribe: (onData: (data: T) => void, onError?: (message: string) => void) => () => void,
  initial: T,
): LiveState<T> {
  const [state, setState] = useState<LiveState<T>>({ data: initial, loading: true, error: null });

  useEffect(() => {
    let active = true;
    const unsubscribe = subscribe(
      (data) => {
        if (!active) return;
        setState({ data, loading: false, error: null });
      },
      (message) => {
        if (!active) return;
        setState({ data: initial, loading: false, error: message || CONFIG_MESSAGE });
      },
    );
    return () => {
      active = false;
      unsubscribe();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return state;
}

