{"kind":"tool","id":"l9TNelw-W3c","toolName":"write_file","input":{"path":"lib/server/seo.ts","content":"import { ADMIN_READY, getAdminDb } from "@/lib/firebase/admin";
import type { Product } from "@/lib/types";

/**
 * Optional server-side product lookup for SEO metadata. It only runs when the
 * Firebase Admin SDK is configured — the UI itself reads from Firestore directly.
 */
export async function fetchProductSeo(
  slug: string,
): Promise<Partial<Product> | null> {
  if (!ADMIN_READY) return null;
  try {
    const snapshot = await getAdminDb()
      .collection("products")
      .where("slug", "==", slug)
      .where("available", "==", true)
      .limit(1)
      .get();
    const doc = snapshot.docs[0];
    if (!doc) return null;
    return doc.data() as Partial<Product>;
  } catch {
    return null;
  }
}

export async function fetchCategorySeo(slug: string): Promise<{ name: string; description: string } | null> {
  if (!ADMIN_READY) return null;
  try {
    const snapshot = await getAdminDb()
      .collection("categories")
      .where("slug", "==", slug)
      .limit(1)
      .get();
    const doc = snapshot.docs[0];
    if (!doc) return null;
    const data = doc.data();
    return { name: String(data.name ?? ""), description: String(data.description ?? "") };
  } catch {
    return null;
  }
}
