import { timingSafeEqual } from "node:crypto";
import { getAdminAuth } from "@/lib/firebase/admin";
import { assertSameOrigin, HttpError, jsonError, rateLimit, requireUser } from "@/lib/server/auth";

export const runtime = "nodejs";

function safeEqual(a: string, b: string) {
  const bufferA = Buffer.from(a);
  const bufferB = Buffer.from(b);
  if (bufferA.length !== bufferB.length) return false;
  return timingSafeEqual(bufferA, bufferB);
}

/**
 * One-time bootstrap for the first administrator.
 *
 * Requires (a) a signed-in Firebase account, (b) the ADMIN_BOOTSTRAP_SECRET env
 * value, and (c) optionally an email pinned via ADMIN_BOOTSTRAP_EMAIL. The role
 * is stored as a custom claim, which clients cannot write.
 */
export async function POST(request: NextRequest) {
  try {
    assertSameOrigin(request);
    const token = await requireUser(request);
    rateLimit(`bootstrap:${token.uid}`, 3, 10 * 60_000);

    const secret = process.env.ADMIN_BOOTSTRAP_SECRET;
    if (!secret) {
      throw new HttpError(
        503,
        "Admin bootstrap is disabled. Set ADMIN_BOOTSTRAP_SECRET in .env.local to enable it.",
      );
    }

    const pinnedEmail = (process.env.ADMIN_BOOTSTRAP_EMAIL ?? "").trim().toLowerCase();
    if (pinnedEmail && (token.email ?? "").toLowerCase() !== pinnedEmail) {
      throw new HttpError(403, "This account is not the configured administrator.");
    }

    const body = (await request.json().catch(() => ({}))) as { secret?: string };
    if (!body.secret || !safeEqual(body.secret, secret)) {
      throw new HttpError(403, "Invalid bootstrap secret.");
    }

    if (token.admin === true) {
      return Response.json({ ok: true, message: "This account is already an administrator." });
    }

    await getAdminAuth().setCustomUserClaims(token.uid, { admin: true });
    return Response.json({
      ok: true,
      message:
        "Admin role granted. Sign out and back in (or refresh your session) to receive the new token.",
    });
  } catch (error) {
    return jsonError(error);
  }
}
