export async function fetchSettings(): Promise<RestaurantSettings> {
  if (!FIREBASE_READY) return DEFAULT_SETTINGS;
  const db = getDb();
  if (!db) return DEFAULT_SETTINGS;
  try {
    const snapshot = await getDoc(doc(db, "restaurantSettings", "main"));
