{"kind":"tool","id":"l9Zvkzw9urY","toolName":"write_file","input":{"path":"app/api/admin/orders/[id]/route.ts","content":"import type { NextRequest } from "next/server";
import { FieldValue } from "firebase-admin/firestore";
import { getAdminDb } from "@/lib/firebase/admin";
import { assertSameOrigin, HttpError, jsonError, requireAdmin } from "@/lib/server/auth";
import { mapOrder } from "@/lib/data/user";
import { ORDER_STATUSES, PAYMENT_STATUSES } from "@/lib/site";

export const runtime = "nodejs";

export async function PATCH(request: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  try {
    assertSameOrigin(request);
    await requireAdmin(request);
    const { id } = await ctx.params;
    const body = (await request.json()) as {
      status?: string;
      paymentStatus?: string;
      adminNotes?: string;
    };

    const db = getAdminDb();
    const ref = db.collection("orders").doc(id);
    const snapshot = await ref.get();
    if (!snapshot.exists) throw new HttpError(404, "Order not found.");
    const current = snapshot.data() as Record<string, unknown>;

    const patch: Record<string, unknown> = { updatedAt: new Date().toISOString() };

    if (body.status) {
      if (!ORDER_STATUSES.includes(body.status as (typeof ORDER_STATUSES)[number])) {
        throw new HttpError(400, "Unknown order status.");
      }
      if (body.status !== current.status) {
        patch.status = body.status;
        patch.statusHistory = FieldValue.arrayUnion({
          status: body.status,
          at: new Date().toISOString(),
          by: "admin",
        });
      }
    }

    if (body.paymentStatus) {
      if (!PAYMENT_STATUSES.includes(body.paymentStatus as (typeof PAYMENT_STATUSES)[number])) {
        throw new HttpError(400, "Unknown payment status.");
      }
      patch.paymentStatus = body.paymentStatus;
    }

    if (typeof body.adminNotes === "string") {
      patch.adminNotes = body.adminNotes.slice(0, 1000);
    }

    await ref.update(patch);
    const updated = await ref.get();
    return Response.json({ order: mapOrder(updated.id, updated.data() as Record<string, unknown>) });
  } catch (error) {
    return jsonError(error);
  }
}
