{"kind":"tool","id":"l-lDpuVhK50","toolName":"write_file","input":{"path":"app/sitemap.ts","content":"import type { MetadataRoute } from "next";
import { ADMIN_READY, getAdminDb } from "@/lib/firebase/admin";

const base = process.env.NEXT_PUBLIC_SITE_URL ?? "http://localhost:3000";

export const revalidate = 3600;

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const staticRoutes: MetadataRoute.Sitemap = [
    { url: `${base}/`, changeFrequency: "weekly", priority: 1 },
    { url: `${base}/menu`, changeFrequency: "daily", priority: 0.9 },
    { url: `${base}/categories`, changeFrequency: "weekly", priority: 0.8 },
    { url: `${base}/about`, changeFrequency: "monthly", priority: 0.6 },
    { url: `${base}/contact`, changeFrequency: "monthly", priority: 0.6 },
  ];

  if (!ADMIN_READY) return staticRoutes;

  try {
    const db = getAdminDb();
    const [products, categories] = await Promise.all([
      db.collection("products").where("available", "==", true).limit(500).get(),
      db.collection("categories").where("active", "==", true).limit(100).get(),
    ]);

    return [
      ...staticRoutes,
      ...categories.docs.map((doc) => ({
        url: `${base}/categories/${doc.data().slug ?? doc.id}`,
        changeFrequency: "weekly" as const,
        priority: 0.7,
      })),
      ...products.docs.map((doc) => ({
        url: `${base}/menu/${doc.data().slug ?? doc.id}`,
        lastModified: doc.data().updatedAt ? new Date(doc.data().updatedAt) : undefined,
        changeFrequency: "weekly" as const,
        priority: 0.8,
      })),
    ];
  } catch {
    return staticRoutes;
  }
