{"kind":"tool","id":"l-moRxZeyvM","toolName":"write_file","input":{"path":"firestore.rules","content":"rules_version = '2';

// UNTOUCH — Firestore security rules
//
// Principles:
//  • Public catalogue reads are limited to *published* documents.
//  • Customers can only read their own profile, addresses and orders.
//  • Admin privileges live in a Firebase custom claim (request.auth.token.admin).
//  • Orders are written exclusively by trusted server code (Admin SDK), so the
//    client can never forge prices, totals or payment state.

service cloud.firestore {
  match /databases/{database}/documents {

    function isSignedIn() {
      return request.auth != null;
    }

    function isAdmin() {
      return isSignedIn() && request.auth.token.admin == true;
    }

    // ── Catalogue ────────────────────────────────────────────────
    match /products/{productId} {
      allow read: if resource.data.available == true || isAdmin();
      allow create, update, delete: if isAdmin();
    }

    match /categories/{categoryId} {
      allow read: if resource.data.active == true || isAdmin();
      allow create, update, delete: if isAdmin();
    }

    match /banners/{bannerId} {
      allow read: if resource.data.active == true || isAdmin();
      allow create, update, delete: if isAdmin();
    }

    match /restaurantSettings/{docId} {
      allow read: if true;
      allow write: if isAdmin();
    }

    // ── Reviews (moderated) ──────────────────────────────────────
    match /reviews/{reviewId} {
      allow read:  [… 564 characters omitted] ──────────
    match /users/{userId} {
      allow read: if isAdmin() || (isSignedIn() && request.auth.uid == userId);

      allow create: if isSignedIn()
        && request.auth.uid == userId
        && request.resource.data.uid == userId
        && !('admin' in request.resource.data)
        && !('role' in request.resource.data);

      allow update: if (
        isSignedIn()
        && request.auth.uid == userId
        && !request.resource.data.diff(resource.data).affectedKeys()
              .hasAny(['admin', 'role', 'uid', 'createdAt'])
      ) || isAdmin();

      allow delete: if isAdmin();
    }

    // ── Addresses ────────────────────────────────────────────────
    match /addresses/{addressId} {
      allow read: if isSignedIn() && (resource.data.userId == request.auth.uid || isAdmin());
      allow create: if isSignedIn() && request.resource.data.userId == request.auth.uid;
      allow update: if isSignedIn()
        && resource.data.userId == request.auth.uid
        && request.resource.data.userId == request.auth.uid;
      allow delete: if isSignedIn() && resource.data.userId == request.auth.uid;
    }

    // ── Orders — server-written only ─────────────────────────────
    match /orders/{orderId} {
      allow read: if isSignedIn() && (resource.data.userId == request.auth.uid || isAdmin());
      allow write: if false;
    }

    // ── Coupons are never readable by clients (no enumeration) ───
    match /coupons/{couponId} {
      allow read, write: if isAdmin();
    }

    // ── Newsletter & contact messages ────────────────────────────
    match /newsletter/{entryId} {
      allow create: if request.resource.data.email is string
        && request.resource.data.email.size() > 3
        && request.resource.data.email.size() < 200;
      allow read, update, delete: if isAdmin();
    }

    match /messages/{messageId} {
      allow create: if request.resource.data.name is string
        && request.resource.data.email is string
        && request.resource.data.message is string
        && request.resource.data.message.size() > 0
        && request.resource.data.message.size() <= 1200;
      allow read, update, delete: if isAdmin();
    }

    // Deny everything not explicitly matched.
    match /{document=**} {
      allow read, write: if false;
    }
  }
}
