{"kind":"tool","id":"l-nJ-wqWO2A","toolName":"write_file","input":{"path":"scripts/load-env.ts","content":"import { readFileSync } from "node:fs";
import { resolve } from "node:path";

/** Minimal .env loader for standalone scripts (no extra dependency). */
export function loadEnv(files = [".env.local", ".env"]) {
  for (const file of files) {
    try {
      const content = readFileSync(resolve(process.cwd(), file), "utf8");
      for (const line of content.split("\n")) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith("#")) continue;
        const index = trimmed.indexOf("=");
        if (index === -1) continue;
        const key = trimmed.slice(0, index).trim();
        let value = trimmed.slice(index + 1).trim();
        if (
          (value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))
        ) {
          value = value.slice(1, -1);
        }
        if (!(key in process.env)) process.env[key] = value;
      }
    } catch {
      /* file missing — fine */
    }
  }
}
