{"kind":"tool","id":"l-r_wK9qdmU","toolName":"write_file","input":{"path":"scripts/grant-admin.ts","content":"/**
 * Grants the admin custom claim to an existing Firebase Auth account.
 *
 *   npm run grant-admin -- owner@untouch.pk
 *
 * The account must have signed up on the site first (email/password or Google).
 * Admins are always created server-side — the browser can never self-assign.
 */
import { loadEnv } from "./load-env";

loadEnv();

import { applicationDefault, cert, getApps, initializeApp } from "firebase-admin/app";
import { getAuth } from "firebase-admin/auth";

function createAdmin() {
  if (getApps().length) return getApps()[0];
  const raw = process.env.FIREBASE_SERVICE_ACCOUNT_JSON;
  if (raw) {
    const json = raw.trim().startsWith("{") ? JSON.parse(raw) : JSON.parse(Buffer.from(raw, "base64").toString("utf8"));
    return initializeApp({ credential: cert(json), projectId: json.project_id });
  }
  const projectId = process.env.FIREBASE_ADMIN_PROJECT_ID || process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID;
  const clientEmail = process.env.FIREBASE_ADMIN_CLIENT_EMAIL;
  const privateKey = process.env.FIREBASE_ADMIN_PRIVATE_KEY?.replace(/\\n/g, "\n");
  if (projectId && clientEmail && privateKey) {
    return initializeApp({ credential: cert({ projectId, clientEmail, privateKey }), projectId });
  }
  return initializeApp({ credential: applicationDefault(), projectId });
}

async function main() {
  const email = process.argv[2];
  if (!email) {
    console.error("Usage: npm run grant-admin -- <email>");
    process.exit(1);
  }

  const app = createAdmin();
  const auth = getAuth(app);
  const user = await auth.getUserByEmail(email);
  const existing = user.customClaims ?? {};

  await auth.setCustomUserClaims(user.uid, { ...existing, admin: true });
  await auth.revokeRefreshTokens(user.uid);

  console.log(`\n✓ ${email} is now an administrator (uid ${user.uid}).`);
  console.log("  Refresh tokens revoked — the user must sign in again for the claim to apply.");
  console.log(`  Admin panel: /unnothingadmin\n`);
}

main().catch((error) => {
  console.error("\nCould not grant admin:", error instanceof Error ? error.message : error);
  console.error(
    "Make sure the account exists in Firebase Authentication and Admin credentials are configured in .env.local.",
  );
  process.exit(1);
});
"}}


